set -euo pipefail
python3 - <<'PY'
import json, pathlib, re, datetime
home=pathlib.Path.home()
roots=[home/'Library/Application Support/Google/Chrome',home/'Library/Application Support/Chromium',home/'Library/Application Support/BraveSoftware/Brave-Browser']
matches=[]
for root in roots:
  if not root.exists(): continue
  for profile in root.iterdir():
    if not profile.is_dir(): continue
    for prefname in ('Preferences','Secure Preferences'):
      pref=profile/prefname
      if not pref.exists(): continue
      try: data=json.loads(pref.read_text())
      except Exception: continue
      for ext_id,ext in (((data.get('extensions') or {}).get('settings') or {})).items():
        raw=json.dumps(ext)
        path=str(ext.get('path') or '')
        name=str((ext.get('manifest') or {}).get('name') or '')
        if 'chat_bridge' in raw.lower() or 'local-agent' in path.lower() or 'Local Agent Chat Bridge' in name:
          key=(str(profile),ext_id)
          if key not in [(str(p),e) for p,e in matches]:
            matches.append((profile,ext_id))
          print('EXTENSION='+json.dumps({'profile':profile.name,'id':ext_id,'pref':prefname,'path':path,'name':name,'version':(ext.get('manifest') or {}).get('version')},sort_keys=True))
print('MATCH_COUNT='+str(len(matches)))
def iso_score(v):
  vals=[]
  for c in (v.get('conversations') or {}).values():
    for k in ('lastControlAt','lastRunAt','nextRunAt'):
      s=c.get(k)
      if isinstance(s,str) and s: vals.append(s)
  return max(vals) if vals else ''
for profile,ext_id in matches:
  storage=profile/'Local Extension Settings'/ext_id
  print(f'STORAGE profile={profile.name} id={ext_id} exists={storage.exists()}')
  states=[]
  if storage.exists():
    dec=json.JSONDecoder()
    for f in storage.iterdir():
      if not f.is_file(): continue
      try: text=f.read_bytes().decode('latin1')
      except Exception: continue
      starts=[m.start() for m in re.finditer(r'\{\"conversations\":',text)]
      for pos in starts:
        try:
          obj,end=dec.raw_decode(text[pos:])
        except Exception:
          continue
        if isinstance(obj,dict) and obj.get('schemaVersion')==2 and isinstance(obj.get('conversations'),dict):
          states.append((iso_score(obj),f.name,obj))
  uniq={}
  for score,f,obj in states:
    sig=json.dumps(obj,sort_keys=True,separators=(',',':'))
    uniq[sig]=(score,f,obj)
  ordered=sorted(uniq.values(),key=lambda x:x[0])
  print('PARSED_STATE_COUNT='+str(len(ordered)))
  for idx,(score,f,obj) in enumerate(ordered[-5:],1):
    compact=[]
    for cid,c in (obj.get('conversations') or {}).items():
      compact.append({k:c.get(k) for k in ('id','url','label','repositoryId','enabled','bootstrapPending','preferredTabId','lastStatus','lastControlAt','lastRunAt','nextRunAt')})
    print('STATE[%d]='%idx+json.dumps({'score':score,'file':f,'conversations':compact},sort_keys=True))
PY

